-- Insert Quiz Questions for Lesson: Think Like a Shopkeeper

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 19 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 19 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'think-like-a-shopkeeper' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson think-like-a-shopkeeper not found in module 19';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the most important rule for your first online store?', 
    '["Offer the lowest price in your market","Start with one well-tested product","Copy your competitor''s entire catalog","List as many products as possible"]'::jsonb,
    'Start with one well-tested product',
    'One well-tested product is more useful than ten unfinished listings. Focus on clarity and quality first.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which of these is a good starter product for a coach?', 
    '["A free consultation with no clear next step","A $2,000 year-long programme","A $5 e-book about general wellness","A $99 introductory coaching package with booking instructions"]'::jsonb,
    'A $99 introductory coaching package with booking instructions',
    'A $99 introductory coaching package is a clear, testable offer with defined delivery through booking instructions or automation.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What must you be able to explain before asking visitors to pay?', 
    '["What the customer receives after purchase","Your personal credentials and degrees","Your competitor''s weaknesses","Your entire business history"]'::jsonb,
    'What the customer receives after purchase',
    'You must be able to tell a visitor what they get before asking them to pay. Clarity builds trust and drives conversions.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
