-- Insert Quiz Questions for Lesson: Create the Store

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 19 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 19 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'create-the-store' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson create-the-store not found in module 19';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where do you find the online store feature in LeadProspectrr?', 
    '["Sites → Stores","Payments → Products","Marketing → Campaigns","Contacts → Smart Lists"]'::jsonb,
    'Sites → Stores',
    'The online store feature is located under Sites → Stores in the left sidebar.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the difference between a store name and a domain?', 
    '["A store name is for your business; a domain is the web address customers visit","A domain is only needed for physical stores","A store name appears on customer receipts","They are the same thing"]'::jsonb,
    'A store name is for your business; a domain is the web address customers visit',
    'A store name identifies your business internally; a domain is the public web address customers will use to visit your store.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do before publishing your store?', 
    '["Save progress and finish all setup first","Add 100 products before publishing","Share the link on social media","Publish immediately to secure the URL"]'::jsonb,
    'Save progress and finish all setup first',
    'Save progress regularly but do not publish an unfinished store. Complete setup and testing before going live.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
