-- Insert Quiz Questions for Lesson: Add Your First Product

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 19 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 19 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'add-your-first-product' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson add-your-first-product not found in module 19';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where do you create a product in LeadProspectrr?', 
    '["Marketing → Social Planner","Payments → Products","Sites → Stores","Automation → Workflows"]'::jsonb,
    'Payments → Products',
    'Products are created under Payments → Products, separate from the store builder.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What setting must be enabled for a product to appear in your store?', 
    '["Include in Online Store","Set as Subscription","Mark as Featured","Enable Reviews"]'::jsonb,
    'Include in Online Store',
    'The Include in Online Store setting must be enabled for the product to appear in your storefront.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should a product description include?', 
    '["Only the product name and price","Your company''s full history","Audience, outcome, deliverables, and what happens after purchase","A list of all your other products"]'::jsonb,
    'Audience, outcome, deliverables, and what happens after purchase',
    'A benefit-led description covers who it is for, what outcome it delivers, what the customer receives, and what happens after purchase.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
