-- Insert Quiz Questions for Lesson: Make the Shop Easy to Use

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 19 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 19 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'make-shop-easy-to-use' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson make-shop-easy-to-use not found in module 19';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which page shows the customer''s order confirmation?', 
    '["Products List","Checkout","Cart","Thank You"]'::jsonb,
    'Thank You',
    'The Thank You page appears after payment and shows order confirmation and next steps.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you preview the store on a phone?', 
    '["Desktop preview is not available","Customers may buy on mobile; layout and actions must work there","Mobile preview is required by law","Phone previews load faster"]'::jsonb,
    'Customers may buy on mobile; layout and actions must work there',
    'Many customers shop on mobile. A good desktop design can still have unreadable text or awkward buttons on a phone.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the five-second shopper test checking?', 
    '["How many products can be viewed in five seconds","If the checkout process takes less than five seconds","Whether a stranger can understand the offer, audience, price, and purchase method quickly","How fast the page loads"]'::jsonb,
    'Whether a stranger can understand the offer, audience, price, and purchase method quickly',
    'The five-second test checks if a stranger can quickly understand what is sold, who it is for, what it costs, and how to buy it.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
